function explainAnswer(q,student,earned){const correct=q.section==='synthesis'?(q.answerContinuation||q.answer):(q.answer||q.acceptedPatterns?.[0]||'');const section=q.section;const common={grammar:'Check the sentence for subject-verb agreement, tense, verb form, articles, pronouns, prepositions and the meaning of the whole sentence.',vocabulary:'Use the meaning of the whole sentence and the surrounding context. Choose the word that fits both meaning and grammar.',vocabularyCloze:'Read the whole passage first. Use nearby clues, the flow of ideas and the meaning of the sentence before choosing the word.',visual:'Go back to the visual text and locate the exact detail or clue that supports the answer. Do not rely on outside knowledge.',grammarCloze:'Use both grammar and the meaning of the passage. Check the words immediately before and after the blank.',editing:'Identify the exact grammatical or spelling error, then replace only the incorrect part while keeping the sentence meaning unchanged.',comprehensionCloze:'Use the surrounding sentences and the overall meaning of the passage. The answer must fit the context, not just the grammar.',synthesis:'Keep the original meaning unchanged. Follow the given starter exactly and write only the continuation required after the blank.',comprehension:'Answer from evidence in the passage. Make sure every important part of the question is addressed.'};let base=q.explanation||common[section]||'Review the language skill tested in this question.';if(section==='vocabulary'&&!q.explanation){const c=String(correct).toLowerCase();if(c==='put together'){base='“Put together” means to assemble or join separate parts into one complete object. It fits the sentence because the pupils had to assemble the robot parts before the robot could move.';}else{base='The correct answer “'+String(correct)+'” fits the blank because its meaning matches the context and the sentence reads naturally with this word or phrase.';}}if(student&&earned===Number(q.marks))return base;if(!student)return base+' You left this question unanswered. Compare the correct answer with the sentence or passage and identify the clue that leads to it.';return base+' Your answer does not match the accepted answer. Compare your response with the correct answer and identify the word, form or meaning that needs to change.'}
function summary(){const n=state.questions.filter(q=>state.answers[q.id]!=null&&String(state.answers[q.id]).trim()!=='').length;return '<strong>'+n+' / 75</strong> questions answered<br><span>'+(75-n)+' unanswered</span>'}
function injectResultReviewStyle(){if(document.getElementById('aplus-result-review-style'))return;const s=document.createElement('style');s.id='aplus-result-review-style';s.textContent='.answer-review{margin-top:28px}.answer-review-title{font-size:22px;color:#17362a;margin:0 0 8px}.answer-review-subtitle{color:#64756d;margin:0 0 18px}.review-card{border:1px solid #dfe8e2;border-radius:14px;background:#fff;margin:12px 0;overflow:hidden}.review-card-head{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:13px 16px;background:#f7faf8;border-bottom:1px solid #e7eee9}.review-card-head strong{color:#17362a}.review-result{font-weight:700}.review-result.correct{color:#2f6b50}.review-result.wrong{color:#a33}.review-result.unanswered{color:#8a6a22}.review-card-body{padding:15px 16px}.review-question{font-weight:600;color:#20362d;line-height:1.55;margin-bottom:12px;white-space:pre-line}.review-line{margin:8px 0;line-height:1.5}.review-label{font-weight:700;color:#53635b}.review-correct-answer{display:inline-block;background:#eef6f1;border-radius:7px;padding:3px 8px;color:#17362a;font-weight:700}.review-student-answer{display:inline-block;background:#f5f6f5;border-radius:7px;padding:3px 8px}.review-explanation{background:#fbfcfb;border-left:3px solid #9ab9a8;padding:10px 12px;margin-top:12px;color:#40564b}.review-source{font-size:12px;color:#7a8982;margin-top:10px}@media(max-width:700px){.review-card-head{align-items:flex-start;flex-direction:column}}';document.head.appendChild(s)}
function scoreAnswer(q,student){
  const input=norm(student);
  if(!input)return 0;
  const max=Number(q&&q.marks)||0;
  if(!q)return 0;

  // MCQ: q.answer may be the correct text or a zero-based option index.
  if(q.type==='mcq'){
    let correct=q.answer;
    if(typeof correct==='number' && Array.isArray(q.options)) correct=q.options[correct];
    if(correct==null && Array.isArray(q.acceptedPatterns)) correct=q.acceptedPatterns[0];
    return norm(correct)===input ? max : 0;
  }

  // Open-ended: accept the explicit accepted patterns first, then q.answer.
  const accepted=[];
  if(Array.isArray(q.acceptedPatterns)) accepted.push(...q.acceptedPatterns);
  if(Array.isArray(q.accepted)) accepted.push(...q.accepted);
  if(q.answer!=null){
    if(typeof q.answer==='number' && Array.isArray(q.options)) accepted.push(q.options[q.answer]);
    else accepted.push(q.answer);
  }
  const candidates=[...new Set(accepted.filter(x=>x!=null).map(norm).filter(Boolean))];
  if(!candidates.length)return 0;

  // Exact normalized match is the default marking rule. This removes punctuation,
  // quotation marks and repeated whitespace differences without changing meaning.
  if(candidates.includes(input))return max;

  // For 1-mark cloze/editing items, also accept a word-for-word answer when the
  // database answer contains a short phrase surrounded by punctuation.
  if(max===1){
    const compact=s=>norm(s).replace(/[^a-z0-9 ]/g,'').trim();
    const ci=compact(input);
    if(candidates.some(x=>compact(x)===ci))return max;
  }
  return 0;
}
function safeScore(q,student){try{return Number(scoreAnswer(q,student))||0}catch(e){console.warn('[APLUS Score]',q&&q.number,e);return 0}}
function result(){
  let total=0;const sec={},skills={};
  state.questions.forEach(q=>{
    const s=safeScore(q,state.answers[q.id]);total+=s;
    sec[q.section]=(sec[q.section]||0)+s;
    const k=q.skill||q.section;skills[k]??={score:0,max:0};
    skills[k].score+=s;skills[k].max+=Number(q.marks)||0;
  });
  $('score').textContent=total+' / 90';
  $('percentage').textContent=Math.round(total/90*100)+'%';
  $('paperId').textContent='Paper ID: '+esc(state.paperId);
  $('resultMessage').textContent=total>=81?'Excellent accuracy':total>=63?'Strong progress':total>=45?'More practice needed':'Let’s rebuild the basics';
  $('sectionResults').innerHTML=BLUEPRINT.map(b=>'<div class="result-row"><span>'+esc(b.name)+'</span><strong>'+(sec[b.id]||0)+' / '+b.marks+'</strong></div>').join('');
  const arr=Object.entries(skills).sort((a,b)=>(b[1].score/b[1].max)-(a[1].score/a[1].max)).slice(0,12);
  $('skillResults').innerHTML='<h3>Skill Profile</h3>'+arr.map(([k,v])=>'<div class="result-row"><span>'+esc(k)+'</span><strong>'+v.score+' / '+v.max+'</strong></div>').join('');
  injectResultReviewStyle();
  const box=$('answerReview');
  if(!box)throw new Error('Answer review container is missing.');
  let reviewHtml='<h3 class="answer-review-title">Answer Review</h3><p class="answer-review-subtitle">Your answer, the correct answer and an explanation are shown below for every question.</p>';
  state.questions.forEach(q=>{
    try{
      const student=String(state.answers[q.id]??'').trim();
      const earned=safeScore(q,student);
      const rawAccepted=Array.isArray(q.acceptedPatterns)?q.acceptedPatterns:[];
      const correct=(q.section==='synthesis'
        ?(q.answerContinuation||q.answer||rawAccepted[0]||'')
        :(typeof q.answer==='number'&&Array.isArray(q.options)
          ?q.options[q.answer]
          :(q.answer||rawAccepted[0]||'')));
      const explanation=explainAnswer(q,student,earned);
      const resultClass=!student?'unanswered':earned===Number(q.marks)?'correct':'wrong';
      const resultText=!student?'Not answered':earned===Number(q.marks)?'Correct':'Needs correction';
      const prompt=q.sourceSentences&&q.starter
        ?(q.sourceSentences.join('\\n')+'\\n\\n'+q.starter+' ________________________________')
        :(q.question||'');
      reviewHtml+='<article class="review-card"><div class="review-card-head"><strong>Question '+q.number+' · '+esc(q.sectionName||q.section)+'</strong><span class="review-result '+resultClass+'">'+resultText+' · '+earned+'/'+(q.marks||0)+'</span></div><div class="review-card-body"><div class="review-question">'+esc(prompt)+'</div><div class="review-line"><span class="review-label">Your answer:</span> <span class="review-student-answer">'+esc(student||'No answer')+'</span></div><div class="review-line"><span class="review-label">Correct answer:</span> <span class="review-correct-answer">'+esc(correct)+'</span></div><div class="review-explanation"><span class="review-label">Explanation:</span> '+esc(explanation)+'</div>'+(q.pattern?'<div class="review-source">Skill: '+esc(q.skill||'')+' · Pattern: '+esc(q.pattern)+'</div>':'')+'</div></article>';
    }catch(e){
      console.warn('[APLUS Answer Review]',q&&q.number,e);
      reviewHtml+='<article class="review-card"><div class="review-card-head"><strong>Question '+esc(q&&q.number||'')+'</strong><span class="review-result unanswered">Review unavailable</span></div><div class="review-card-body"><div class="review-question">'+esc(q&&q.question||'')+'</div><div class="review-line"><span class="review-label">Your answer:</span> <span class="review-student-answer">'+esc(state.answers[q.id]||'No answer')+'</span></div></div></article>';
    }
  });
  box.innerHTML=reviewHtml;
  show('result');
  window.setTimeout(()=>{const resultScreen=$('result');if(resultScreen&&resultScreen.classList.contains('active'))window.scrollTo({top:0,left:0,behavior:'auto'})},0);
}
function submit(auto){if(state.submitted)return;if(!auto&&!window.confirm('Submit this paper? Your answers will be locked for this attempt.'))return;state.submitted=true;state.submittedAt=Date.now();clearInterval(timer);try{localStorage.setItem(DONE,JSON.stringify(state));localStorage.removeItem(KEY)}catch(e){}try{result()}catch(e){console.error('[APLUS Result]',e);const rs=$('result');if(rs){show('result');const msg=rs.querySelector('.result-paper');if(msg)msg.insertAdjacentHTML('beforeend','<div style="margin:20px 0;padding:16px;border:1px solid #e2b8b8;background:#fff7f7;border-radius:12px"><strong>Result generated</strong><p>There was a problem loading the detailed answer review. Please refresh the page to view your result.</p></div>')}}}
async function generate(){const btn=$('startBtn');if(btn)btn.disabled=true;try{status('Checking generator…');await readyPromise;const profile=$('paperProfile')?.value||'standard',candidate=$('candidateName')?.value.trim()||'',className=$('candidateClass')?.value.trim()||'',seed=(Math.random()*4294967295)>>>0;const out=generatePaper(profile,seed);state={version:'10.2',started:true,submitted:false,index:0,remaining:TOTAL,questions:out.paper.map((q,i)=>Object.assign({},q,{number:i+1,id:q.id||('P2-'+out.seed+'-'+(i+1)),sectionName:(BLUEPRINT.find(b=>b.id===q.section)||{}).name||q.section})),answers:{},candidate,className,profile,paperId:'APLUS-P6-ENG-P2-'+new Date().getFullYear()+'-'+String(out.seed%1000000).padStart(6,'0'),seed:out.seed,startedAt:Date.now(),submittedAt:0};save();status('Paper generated successfully · 75 questions · 90 marks',true);show('exam');startClock();renderQuestion()}catch(e){console.error('[APLUS Prelim V10.4]',e);status('Generation failed: '+(e.message||String(e)),false);window.setTimeout(()=>window.alert('APLUS Prelim Generator\n\nGeneration failed:\n'+(e.message||String(e))+'\n\nNo incomplete paper was opened.'),20)}finally{if(btn)btn.disabled=false}}
function load(){try{const x=JSON.parse(localStorage.getItem(KEY)||'null');if(x&&x.version==='10.2'&&Array.isArray(x.questions)&&x.questions.length===75){state=Object.assign(state,x);$('resumeBtn')?.classList.remove('hidden');return true}}catch(e){}return false}
function resume(){if(!load())return;show('exam');startClock();renderQuestion()}
function review(){show('exam');renderQuestion()}
function printPaper(){const w=window.open('','_blank');if(!w)return;const rows=state.questions.map(q=>'<section style="page-break-inside:avoid;margin:0 0 24px"><h3>Question '+q.number+' · '+esc(q.sectionName||q.section)+'</h3>'+(q.visual?(Array.isArray(q.visual.texts)?'<div>'+q.visual.texts.map(t=>'<h4>'+esc(t.label||'TEXT')+' · '+esc(t.heading||'')+'</h4><ul>'+t.lines.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>').join('')+'</div>':'<pre>'+esc(q.visual.text||'')+'</pre>'):'')+(q.passage?'<div>'+esc(q.passage).replace(/\n/g,'<br>')+'</div>':'')+'<p><b>'+esc(q.question)+'</b></p>'+(q.options?'<ol type="A">'+q.options.map(o=>'<li>'+esc(o)+'</li>').join('')+'</ol>':'')+'<p><b>Student answer:</b> '+esc(state.answers[q.id]||'')+'</p></section>').join('');w.document.write('<!doctype html><html><head><title>APLUS P6 English Prelim</title><style>body{font-family:Arial;max-width:850px;margin:30px auto;line-height:1.5}pre{white-space:pre-wrap;border:1px solid #ccc;padding:12px}</style></head><body><h1>APLUS P6 English Prelim</h1><p>PSLE-Style English Language Examination · Paper 2</p><p>Candidate: '+esc(state.candidate)+' · Class: '+esc(state.className)+'</p><p>Paper ID: '+esc(state.paperId)+'</p>'+rows+'</body></html>');w.document.close();w.focus();w.print()}
function injectPsleMcqStyle(){if(document.getElementById('aplus-psle-mcq-layout'))return;const s=document.createElement('style');s.id='aplus-psle-mcq-layout';s.textContent=`.psle-options{display:flex;flex-direction:column;gap:0;margin-top:22px}.psle-option{display:grid!important;grid-template-columns:30px 34px minmax(0,1fr);align-items:center;column-gap:0!important;min-height:52px!important;padding:10px 12px!important;margin:0!important;border:0!important;border-bottom:1px solid #e6ece8!important;border-radius:0!important;background:transparent!important;box-sizing:border-box}.psle-option:first-child{border-top:1px solid #e6ece8!important}.psle-option:hover{background:#f7faf8!important}.psle-option input{width:18px!important;height:18px!important;margin:0!important;accent-color:#2f6b50}.psle-option .option-letter{font-weight:700!important;color:#17362a!important;font-size:16px!important;line-height:1.4!important;white-space:nowrap!important}.psle-option .option-answer{font-size:16px!important;line-height:1.45!important;color:#20362d!important;min-width:0!important;overflow-wrap:normal!important;word-break:normal!important}@media(max-width:760px){.psle-option{grid-template-columns:28px 30px minmax(0,1fr);min-height:48px!important;padding:9px 8px!important}.psle-option .option-letter,.psle-option .option-answer{font-size:15px!important}}`;document.head.appendChild(s);const v=document.createElement('script');v.src='prelim-visual-text-module-v2-20260918.js?v=20260918';v.async=true;document.head.appendChild(v)}
function wire(){injectPsleMcqStyle();const start=$('startBtn');if(start){start.onclick=generate;start.type='button'}if($('resumeBtn'))$('resumeBtn').onclick=resume;if($('prevBtn'))$('prevBtn').onclick=()=>{if(state.index>0){state.index--;save();renderQuestion()}};if($('nextBtn'))$('nextBtn').onclick=()=>{if(state.index<74){state.index++;save();renderQuestion()}else{show('submitScreen');$('submitSummary').innerHTML=summary()}};if($('confirmSubmitBtn'))$('confirmSubmitBtn').onclick=()=>submit(false);if($('backToExamBtn'))$('backToExamBtn').onclick=()=>{show('exam');renderQuestion()};if($('reviewBtn'))$('reviewBtn').onclick=review;if($('printBtn'))$('printBtn').onclick=printPaper;if($('newExamBtn'))$('newExamBtn').onclick=()=>{try{localStorage.removeItem(DONE);localStorage.removeItem(KEY)}catch(e){}show('landing');status('Ready for a new Paper 2',true)};load()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',wire);else wire();
window.APLUS_P6_PRELIM_V10={generate,blueprint:BLUEPRINT};
